 static String now(){return Instant.now().truncatedTo(ChronoUnit.MILLIS).toString();}int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}TextView text(String value,int size){TextView t=new TextView(getContext());t.setText(value);t.setTextSize(size);t.setTextColor(dark?Color.WHITE:Color.rgb(25,32,42));t.setPadding(dp(6),dp(5),dp(6),dp(5));t.setMinHeight(dp(48));return t;}
 final class ToolScroll extends ScrollView{int maximumHeight;ToolScroll(Context c){super(c);}protected void onMeasure(int w,int h){if(maximumHeight>0)h=MeasureSpec.makeMeasureSpec(Math.min(maximumHeight,MeasureSpec.getSize(h)),MeasureSpec.AT_MOST);super.onMeasure(w,h);}}
 final class SpinnerColors extends ArrayAdapter<String>{SpinnerColors(List<String> values){super(IndustryDiscoveryScreen.this.getContext(),android.R.layout.simple_spinner_item,values);setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);}View style(View v,ViewGroup parent){TextView t=(TextView)v;t.setMinimumHeight(dp(48));t.setGravity(Gravity.CENTER_VERTICAL);t.setPadding(dp(8),0,dp(8),0);t.setSingleLine(true);t.setEnabled(parent.isEnabled());t.setTextColor(ink());t.setBackgroundColor(surface());return t;}public View getView(int p,View old,ViewGroup parent){return style(super.getView(p,old,parent),parent);}public View getDropDownView(int p,View old,ViewGroup parent){return style(super.getDropDownView(p,old,parent),parent);}}
 int surface(){return dark?Color.rgb(20,29,42):Color.WHITE;}ColorStateList states(int enabled,int disabled){return new ColorStateList(new int[][]{new int[]{-android.R.attr.state_enabled},new int[]{}},new int[]{disabled,enabled});}ColorStateList ink(){return states(dark?Color.rgb(241,245,249):Color.rgb(31,41,55),dark?Color.rgb(148,163,184):Color.rgb(100,116,139));}
 protected void onMeasure(int width,int height){int w=MeasureSpec.getSize(width),h=MeasureSpec.getSize(height);boolean landscape=w>=dp(480)&&w>h;if(wide!=landscape){wide=landscape;setOrientation(wide?HORIZONTAL:VERTICAL);tools.setLayoutParams(wide?new LayoutParams(Math.min(dp(260),Math.max(dp(220),w/3)),-1):new LayoutParams(-1,-2));content.setLayoutParams(wide?new LayoutParams(0,-1,1):new LayoutParams(-1,0,1));scopeControls.setVisibility((pane.getSelectedItemPosition()==0||pane.getSelectedItemPosition()==2)&&(wide||filtersExpanded)?VISIBLE:GONE);filtersToggle.setVisibility(!wide&&(pane.getSelectedItemPosition()==0||pane.getSelectedItemPosition()==2)?VISIBLE:GONE);}tools.maximumHeight=wide?0:Math.max(dp(48),h/2);super.onMeasure(width,height);}
 LinearLayout row(LinearLayout parent){LinearLayout r=new LinearLayout(getContext());r.setOrientation(HORIZONTAL);HorizontalScrollView s=new HorizontalScrollView(getContext());s.addView(r);parent.addView(s);return r;}Button button(LinearLayout parent,String title,String tag,Action action){Button b=new Button(getContext());b.setText(title);b.setTag(tag);b.setMinHeight(dp(48));parent.addView(b);lockable.add(b);b.setOnClickListener(v->{try{action.run();}catch(Exception e){error(e);}});return b;}Spinner spinner(LinearLayout parent,String tag,String[] labels){Spinner s=new Spinner(getContext());s.setTag(tag);s.setMinimumHeight(dp(48));s.setAdapter(new SpinnerColors(Arrays.asList(labels)));parent.addView(s);lockable.add(s);return s;}
 String tax(){return taxonomy.getSelectedItemPosition()==0?"concept":"industry";}String source(){return provider.getSelectedItemPosition()==0?"sina-public-"+tax():"eastmoney-public-board";}JSONObject catalogQuery()throws Exception{return SectorWatchModel.query(source(),tax(),"");}JSONObject memberQuery()throws Exception{JSONObject s=selected();IndustryDiscoveryModel.need(s!=null,"先选择完整供应商身份");return SectorWatchModel.query(s.getString("provider"),s.getString("taxonomy"),s.getString("code"));}JSONObject selected()throws Exception{JSONArray items=state.getJSONArray("items");for(int i=0;i<items.length();i++)if(items.getJSONObject(i).getString("key").equals(selectedKey))return items.getJSONObject(i);return null;}JSONObject topic()throws Exception{JSONArray items=state.getJSONArray("topics");for(int i=0;i<items.length();i++)if(items.getJSONObject(i).getString("key").equals(selectedKey))return items.getJSONObject(i);return null;}
 void error(Exception e){message.setText(e.getMessage()==null?e.getClass().getSimpleName():e.getMessage());controls();}void remember()throws Exception{if(!noteKey.isEmpty())drafts.put(noteKey,note.getText().toString());}
 void controls(){for(View v:lockable)v.setEnabled(active&&!closed&&!busy);try{JSONObject s=selected(),t=topic();fetch.setEnabled(active&&!busy&&!closed&&network&&state.getJSONArray("history").length()<30);stop.setEnabled(busy||deferred!=null);open.setEnabled(!busy&&s!=null);fetchMembers.setEnabled(active&&!busy&&!closed&&network&&s!=null);track.setEnabled(active&&!busy&&!closed&&s!=null&&s.getBoolean("active")&&t==null&&acknowledgement.isChecked());materials.setEnabled(!busy&&t!=null&&host.supportsMaterials());materials.setVisibility(host.supportsMaterials()?VISIBLE:GONE);confirmImport.setEnabled(active&&!busy&&!closed&&preview!=null);previous.setEnabled(!busy&&offset>0);next.setEnabled(!busy&&offset+24<rows.length());removeHistory.setEnabled(!busy&&!historyId.isEmpty());}catch(Exception e){message.setText(e.getMessage());}}
 void cancel(){cancelled.set(true);generation++;if(job!=null)job.cancel(true);feed.cancel();busy=false;controls();}
 void run(Work work,Done done){cancel();cancelled=new AtomicBoolean();AtomicBoolean flag=cancelled;long token=generation;busy=true;controls();job=worker.submit(()->{JSONObject result=null;Exception error=null;try{result=work.run(flag);}catch(Exception e){error=e;}JSONObject value=result;Exception failure=error;main.post(()->{if(closed||flag.get()||token!=generation)return;busy=false;try{if(failure!=null)throw failure;done.run(value);}catch(Exception e){error(e);}controls();});});}
 void load(){if(!active||closed)return;String key=selectedKey;run(flag->{JSONObject s=store.read(flag::get),result=new JSONObject().put("state",s);JSONArray items=s.getJSONArray("items");for(int i=0;i<items.length();i++){JSONObject b=items.getJSONObject(i);if(b.getString("key").equals(key))result.put("members",store.members(SectorWatchModel.query(b.getString("provider"),b.getString("taxonomy"),b.getString("code")),flag::get));}return result;},r->{memberCache=r.optJSONObject("members");if(memberCache==null)memberCache=new JSONObject();accept(r.getJSONObject("state"));if(deferred!=null)beginPreview();});}
 void accept(JSONObject s)throws Exception{IndustryDiscoveryModel.validate(s);state=s;rendering=true;historyIds.clear();List<String> labels=new ArrayList<>();JSONArray history=s.getJSONArray("history");for(int i=history.length()-1;i>=0;i--){JSONObject h=history.getJSONObject(i),snapshot=h.getJSONObject("snapshot"),q=snapshot.getJSONObject("query");historyIds.add(h.getString("id"));labels.add(snapshot.getString("fetchedAt")+" · "+q.getString("provider")+" · "+q.getString("taxonomy")+" · "+h.getString("provenance"));}if(labels.isEmpty())labels.add("暂无目录历史");histories.setAdapter(new SpinnerColors(labels));int index=historyIds.indexOf(historyId);if(historyId.isEmpty()&&!historyIds.isEmpty())index=0;if(index>=0){histories.setSelection(index);historyId=historyIds.get(index);}else historyId="";rendering=false;render();}
 void fetchCatalog()throws Exception{IndustryDiscoveryModel.need(network&&active&&!busy,"当前不能抓取公开目录");JSONObject q=catalogQuery();message.setText("仅当前供应商/分类目录，8秒总截止；不换源、不启用AI");run(flag->{JSONObject snapshot;try{snapshot=feed.fetch(q,flag::get);}catch(Exception e){IndustryDiscoveryModel.active(flag::get);store.failure(q,shortError(e),now(),flag::get);return store.read(flag::get);}store.catalog(snapshot,flag::get);return store.read(flag::get);},s->{accept(s);message.setText("目录观测已记录；覆盖和失败见所选详情，AI未执行");});}
 static String shortError(Exception e){String s=e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();return s.length()>1000?s.substring(0,1000):s;}
 void fetchMembers()throws Exception{IndustryDiscoveryModel.need(network&&active&&!busy,"当前不能读取供应商成分");JSONObject q=memberQuery();run(flag->{JSONObject snapshot=new JSONObject();String failure="";try{snapshot=feed.fetch(q,flag::get);}catch(Exception e){IndustryDiscoveryModel.active(flag::get);failure=shortError(e);}store.members(q,snapshot,failure,now(),flag::get);return store.members(q,flag::get);},r->{memberCache=r;renderDetails();});}
 void select(String key)throws Exception{remember();selectedKey=key;memberCache=new JSONObject();noteKey=key;JSONObject t=topic();note.setText(drafts.optString(key,t==null?"":t.optString("note")));acknowledgement.setChecked(false);rendering=true;pane.setSelection(1);rendering=false;render();JSONObject q=memberQuery();run(flag->store.members(q,flag::get),r->{memberCache=r;renderDetails();});}
 void track()throws Exception{JSONObject updated=IndustryDiscoveryModel.confirm(state,selectedKey,note.getText().toString(),now(),acknowledgement.isChecked());if(SectorWatchModel.equal(updated,state)){message.setText("该项已加入本机候选");return;}long revision=state.getLong("revision");run(flag->{store.save(updated,revision,flag::get);return store.read(flag::get);},s->{accept(s);message.setText("已确认加入本机候选；仅目录线索，自动关闭，在线AI未执行");});}
 void deleteHistory()throws Exception{JSONObject updated=new JSONObject(state.toString());JSONArray kept=new JSONArray(),old=state.getJSONArray("history");for(int i=0;i<old.length();i++)if(!old.getJSONObject(i).getString("id").equals(historyId))kept.put(old.getJSONObject(i));long revision=state.getLong("revision");updated.put("history",kept).put("revision",revision+1);run(flag->{store.save(updated,revision,flag::get);return store.read(flag::get);},s->{historyId="";accept(s);});}
 void render(){try{int p=Math.max(0,pane.getSelectedItemPosition());scopeControls.setVisibility((p==0||p==2)&&(wide||filtersExpanded)?VISIBLE:GONE);filtersToggle.setVisibility(!wide&&(p==0||p==2)?VISIBLE:GONE);status.setVisibility(p==0?VISIBLE:GONE);fetch.setVisibility(p==0?VISIBLE:GONE);directory.setVisibility(p==0?VISIBLE:GONE);View pager=(View)previous.getParent().getParent();pager.setVisibility(p==0?VISIBLE:GONE);detailScroll.setVisibility(p==1?VISIBLE:GONE);topics.setVisibility(p==2?VISIBLE:GONE);historyScroll.setVisibility(p==3?VISIBLE:GONE);importScroll.setVisibility(p==4?VISIBLE:GONE);renderDirectory();renderTopics();renderDetails();renderHistory();controls();}catch(Exception e){error(e);}}
 void renderDirectory()throws Exception{String[] statuses={"all","new","tracked","untracked","inactive"};rows=IndustryDiscoveryModel.list(state,source(),tax(),filter.getText().toString().trim(),statuses[Math.max(0,status.getSelectedItemPosition())],now());offset=Math.max(0,Math.min(offset,Math.max(0,((rows.length()-1)/24)*24)));directoryAdapter.notifyDataSetChanged();paging.setText(rows.length()+"项 · "+(offset/24+1)+"/"+Math.max(1,(rows.length()+23)/24)+"页 · 每页24项");controls();}
